      /* Light Brown & Dark Brown Harness-Style Palette */
      .brand-p {
        fill: #E8B98A;
        stroke: #21130B;
        stroke-width: 8px;
        stroke-linejoin: round;
        stroke-linecap: round;
        paint-order: stroke fill;
      }

      .brand-body {
        fill: #8E5431;
        stroke: #21130B;
        stroke-width: 6px;
        stroke-linejoin: round;
        stroke-linecap: round;
        paint-order: stroke fill;
      }

      .brand-kva {
        fill: #E8B98A;
        stroke: #21130B;
        stroke-width: 8px;
        stroke-linejoin: round;
        stroke-linecap: round;
        paint-order: stroke fill;
      }

      .hero-title {
        font-family: -apple-system, BlinkMacSystemFont, 'SF Pro Text', 'Inter', 'Segoe UI', 'Helvetica Neue', sans-serif;
        font-weight: 600;
        font-size: 14.5px;
        letter-spacing: 3px;
        text-anchor: middle;
        fill: #CBB4A0;
      }

      @media (prefers-color-scheme: light) {
        .brand-p {
          fill: #4A2810 !important;
          stroke: #F4EAE0 !important;
        }
        .brand-body {
          fill: #783F1C !important;
          stroke: #FAF5F0 !important;
        }
        .brand-kva {
          fill: #4A2810 !important;
          stroke: #F4EAE0 !important;
        }
        .hero-title {
          fill: #5C381E !important;
        }
      }
